// A prescribed-action-potential, current-conserving forward model.
// Not an ionic or bidomain propagation solver: AP shapes and activation times
// are prescribed. Extracellular voltages follow from the spatial currents.
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
const smooth=v=>{v=clamp(v);return v*v*(3-2*v);};
const lerp=(a,b,u)=>a+(b-a)*u;
const DURATION=600,REST=-90,PEAK=20,RECOVERY_WIDTH=70;
const CURRENT_REFERENCE=825; // fixed ideal peak axial current for the 40 ms strand
const optionsFor=options=>({geometry:options?.geometry==='near'?'near':'distant',earlyRepolarization:!!options?.earlyRepolarization});
function inverseSmooth(v){let a=0,b=1;for(let i=0;i<50;i++){const m=(a+b)/2;if(smooth(m)<v)a=m;else b=m;}return(a+b)/2;}
// APD80: maximum upstroke to 80% repolarization of the -90 to +20 mV AP.
const RECOVERY_Q80={plain:inverseSmooth(.8),notched:inverseSmooth(1-((PEAK-REST)*.2)/(15-REST))};

export const waveModelMetadata=Object.freeze({
  name:'Prescribed APs + current-conserving volume-conductor model',durationMs:DURATION,
  marker:'APD80',recoveryMarkerMv:-68,
  voltageCalibration:'One fixed illustrative gain for both electrode geometries. The original near-electrode, notched reference gives +0.85 mV at 100 ms. Moving the electrodes changes the actual computed amplitude; no per-geometry normalization is applied.',
  defaultGeometry:'distant',
  geometries:{distant:{radius:10,label:'Distant electrodes',description:'Electrodes are at ±10 strand half-lengths. The lead sensitivity is nearly uniform over this small strand.'},near:{radius:2.15,label:'Near-end electrodes',description:'Electrodes are at ±2.15 strand half-lengths. The same source produces a larger signal near either end because the lead is more sensitive there.'}},
  currentGlyph:'A schematic closed current path is placed at source-weighted centroids. Default direction view enlarges weak-current arrows with fixed visual size and speed; the fixed-reference numerical magnitude is reported separately. Optional strength view scales the glyphs with current. Exact-zero sources draw no flow. This is not a solved electric-field line or extracellular streamline.',
  limitation:'AP waveform and propagation timing are prescribed, not calculated from ion-channel kinetics. Human timing means are the default; waveform shapes and intermediate locations remain simulated. The simplified default has no phase-1 notch. An optional imposed 5 mV early-repolarization notch is an exploration, not a measured feature of the cited timing data.',
  human:{
    citation:'Boukens et al., Cardiovascular Research (2015), doi:10.1093/cvr/cvv202',
    url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC4571834/',
    preparation:'Ten human LV wedges, 1 Hz endocardial pacing, optical APs and simultaneous pseudo-ECG.',
    provenance:'APD and RT are published group means. Endpoint AT is derived as RT minus APD. Intermediate values and all waveform shapes are simulated.',
    originalEndpoints:{first:{at:4,apd:360,rt:364},last:{at:32,apd:317,rt:349}},viewOffsetMs:80,
    markerNote:'The paper used an 80% repolarization-based timing measure. The reduced waveform fixes its 80% crossing exactly; it does not reproduce the original optical waveform or derivative.'
  }
});

export function waveCellVoltage(timeMs,activationMs,apdMs,options={}){
  const notched=!!options.earlyRepolarization;
  const rise=smooth((timeMs-(activationMs-2))/4);
  // No early notch is implied by the human timing means. The optional notch
  // deliberately isolates the small voltage generated by early repolarization.
  const notch=notched?5*smooth((timeMs-(activationMs+2))/12):0;
  const beforeRecovery=REST+(PEAK-REST)*rise-notch;
  const recoveryStart=activationMs+apdMs-RECOVERY_WIDTH*(notched?RECOVERY_Q80.notched:RECOVERY_Q80.plain);
  const recover=smooth((timeMs-recoveryStart)/RECOVERY_WIDTH);
  return REST+(beforeRecovery-REST)*(1-recover);
}

function prescribedState(p,shortening=60,uniform=false,preset='human',count=81,options={}){
  options=optionsFor(options);
  p=clamp(Number.isFinite(p)?p:0);count=Math.max(3,Math.round(Number.isFinite(count)?count:81));
  shortening=clamp(Number.isFinite(+shortening)?+shortening:60,0,100);preset=preset==='explore'?'explore':'human';
  const human=preset==='human',viewOffsetMs=human?80:0,timeMs=p*DURATION;
  const first=human?{at:4,apd:360}:{at:80,apd:300};
  const last=human?{at:32,apd:317}:{at:120,apd:300-shortening};
  const cells=Array.from({length:count},(_,i)=>{
    const u=i/(count-1),timingU=uniform?0:u;
    const originalAT=lerp(first.at,last.at,timingU),apd=lerp(first.apd,last.apd,timingU);
    const at=originalAT+viewOffsetMs,rt=at+apd,recoveryStart=rt-RECOVERY_WIDTH*(options.earlyRepolarization?RECOVERY_Q80.notched:RECOVERY_Q80.plain);
    const vm=waveCellVoltage(timeMs,at,apd,options);
    return{x:2*u-1,y:0,u,at,apd,rt,originalAT,originalRT:originalAT+apd,
      activationMs:at,apdMs:apd,recoveryMs:rt,recoveryStartMs:recoveryStart,recoveryEndMs:recoveryStart+RECOVERY_WIDTH,
      vm,fraction:clamp((vm-REST)/(PEAK-REST)),activating:timeMs>=at-2&&timeMs<=at+2,
      earlyRecovering:options.earlyRepolarization&&timeMs>at+2&&timeMs<at+14,
      recovering:timeMs>recoveryStart&&timeMs<recoveryStart+RECOVERY_WIDTH};
  });
  // Sealed-end finite-volume current balance: source = axial inflow - outflow.
  const dx=2/(count-1),edge=Array(count+1).fill(0);
  for(let i=0;i<count-1;i++)edge[i+1]=-(cells[i+1].vm-cells[i].vm)/dx;
  const sources=cells.map((cell,i)=>({...cell,I:edge[i]-edge[i+1]}));
  const sourceSum=sources.reduce((v,c)=>v+c.I,0),dipole=sources.reduce((v,c)=>v+c.I*c.x,0);
  const centroid=sign=>{let total=0,moment=0;for(const c of sources)if(sign*c.I>0){const w=sign*c.I;total+=w;moment+=w*c.x;}return{x:total>1e-12?moment/total:0,total};};
  const sourceCentroids={source:centroid(1),sink:centroid(-1)};
  const maxAxialCurrent=Math.max(...edge.map(Math.abs));
  const vmRange={min:Math.min(...cells.map(c=>c.vm)),max:Math.max(...cells.map(c=>c.vm))};
  const endpoint=c=>({at:c.at,apd:c.apd,rt:c.rt,originalAT:c.originalAT,originalRT:c.originalRT});
  const endpoints={first:endpoint(cells[0]),last:endpoint(cells.at(-1))};
  const recoverySpan=endpoints.last.rt-endpoints.first.rt,activationSpan=endpoints.last.at-endpoints.first.at;
  const recoveryOrder=Math.abs(recoverySpan)<1e-8?'synchronized':recoverySpan<0?'reverse':'same';
  const minAT=Math.min(...cells.map(c=>c.at)),maxAT=Math.max(...cells.map(c=>c.at));
  const minRecovery=Math.min(...cells.map(c=>c.recoveryStartMs)),maxRecovery=Math.max(...cells.map(c=>c.recoveryEndMs));
  const phase=timeMs<minAT-2?'rest':timeMs<=maxAT+2?'depolarization':timeMs<minRecovery?'plateau':timeMs<maxRecovery?'repolarization':'rest';
  const activeProcesses=[];
  if(cells.some(c=>c.activating))activeProcesses.push('activation');
  if(cells.some(c=>c.earlyRecovering))activeProcesses.push('early-repolarization');
  if(cells.some(c=>c.recovering))activeProcesses.push('recovery');
  const phaseDetail=activeProcesses.includes('activation')?'activation':activeProcesses.includes('early-repolarization')?'early-repolarization':activeProcesses.includes('recovery')?'recovery':phase==='plateau'?'plateau':'rest';
  const phaseLabel={rest:'Resting strand',activation:'Activation', 'early-repolarization':'Early repolarization · imposed notch',plateau:'Plateau',recovery:'Final recovery'}[phaseDetail];
  return{p,timeMs,timeOriginalMs:timeMs-viewOffsetMs,durationMs:DURATION,viewOffsetMs,preset,
    shortening:human?43:shortening,uniform,cells,edge,sources,sourceSum,dipole,phase,phaseDetail,phaseLabel,activeProcesses,
    recoveryOrder,activationSpan,recoverySpan,endpoints,sourceCentroids,maxAxialCurrent,
    currentRelative:Math.min(1,maxAxialCurrent/CURRENT_REFERENCE),currentReference:CURRENT_REFERENCE,
    vmRange,vmSpread:vmRange.max-vmRange.min,options,
    metadata:{...waveModelMetadata,preset,uniform,endpoints,sourceSum,options,
      timingProvenance:uniform?'Uniform control: every simulated location shares the first location’s AP.':human?waveModelMetadata.human.provenance:'User-controlled APD gradient and prescribed activation sequence.'}};
}
function rawPotential(sources,x,y){
  let v=0;
  // Parallel filaments in a homogeneous unbounded conductor; softened sources.
  for(const c of sources)for(const sy of[-.12,0,.12])v+=c.I/(3*Math.sqrt((x-c.x)**2+(y-sy)**2+.06**2));
  return v;
}
// Keep the original gain so a distance comparison preserves attenuation.
const reference=prescribedState(100/DURATION,60,false,'explore',81,{earlyRepolarization:true});
const SCALE=.85/(rawPotential(reference.sources,2.15,0)-rawPotential(reference.sources,-2.15,0));
export function waveLeadSensitivity(x,radius=10){
  let s=0;for(const y of[-.12,0,.12]){const a=radius-x,b=-radius-x;s+=(a/(a*a+y*y+.06**2)**1.5-b/(b*b+y*y+.06**2)**1.5)/3;}return s;
}
export function waveState(p,shortening=60,uniform=false,preset='human',count=81,options={}){
  options=optionsFor(options);
  const state=prescribedState(p,shortening,uniform,preset,count,options);
  const geometry=options.geometry,radius=geometry==='near'?2.15:10,plus={x:radius,y:0},minus={x:-radius,y:0};
  const vp=rawPotential(state.sources,plus.x,plus.y)*SCALE,vn=rawPotential(state.sources,minus.x,minus.y)*SCALE;
  const center=waveLeadSensitivity(0,radius),edge=waveLeadSensitivity(1,radius);
  return{...state,plus,minus,vp,vn,voltage:vp-vn,geometry,electrodeRadius:radius,gain:SCALE,sensitivity:{center,edge,edgeToCenter:edge/center}};
}
export function waveVoltage(p,shortening=60,uniform=false,preset='human',options={}){
  return waveState(p,shortening,uniform,preset,81,options).voltage;
}
